// Multivariate analysis of variance from sequential model projections and generalized roots.
// Formulas, QR, and eigendecompositions use rStats.js' own model and linear-algebra layers.

import { pf1 } from "../distributions/f.js";
import { eigen } from "../linalg/eigen.js";
import { qr, qrCoef, qrFitted, qrResid } from "../linalg/qr.js";
import { design } from "../models/modelMatrix.js";
import { parseFormula } from "../models/formula.js";
import type { DataFrame } from "../models/modelFrame.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const MANOVA_KEYS = ["tol"] as const;
const MANOVA_SUMMARY_KEYS = ["tol", "intercept"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** Name of a multivariate test statistic.
 * @category Multivariate analysis
 */
export type ManovaTestName = "Pillai" | "Wilks" | "Hotelling-Lawley" | "Roy";
/** Numerical options for MANOVA.
 * @category Multivariate analysis
 */
export interface ManovaOptions {
  /** Numerical tolerance used to determine matrix and residual ranks. Default 1e-7. */
  tol?: number;
}
/** Options for MANOVA summary tables.
 * @category Multivariate analysis
 */
export interface ManovaSummaryOptions {
  /** Numerical tolerance used when recomputing the generalized roots. Default 1e-7. */
  tol?: number;
  /** Include the sequential intercept row when the fitted model has one. Default false. */
  intercept?: boolean;
}
/** A labelled matrix table.
 * @category Multivariate analysis
 */
export interface MatrixTable {
  /** Row labels; a scalar string is used for a one-row table. */
  rows: string[];
  /** Column labels, or null for a matrix without named columns. */
  cols: string[] | null;
  /** Numeric table entries in row-major order. */
  values: number[][];
}
/** A fitted sequential MANOVA model.
 * @category Multivariate analysis
 */
export interface ManovaFit {
  /** Formula used to fit the model. */
  formula: string;
  /** Names or expressions of the response variables in formula order. */
  responseNames: string[];
  /** Sequential model terms in formula order. */
  termNames: string[];
  /** Degrees of freedom contributed by each sequential term. */
  termDf: number[];
  /** Residual degrees of freedom. */
  residualDf: number;
  /** Residual sum-of-squares-and-cross-products matrix on the original response scales. */
  residualSSP: number[][];
  /** Sum-of-squares-and-cross-products matrix for each fitted term, keyed by term name. */
  termSSP: Record<string, number[][]>;
  /** Generalized roots for each fitted term, keyed by term name. */
  termRoots: Record<string, number[]>;
  /** Regression coefficient matrix, with terms in rows and responses in columns. */
  coefficients: number[][];
  /** Names of the coefficient rows. */
  coefficientNames: string[];
  /** Power-of-two scale factors used internally for each response. */
  responseScales: number[];
  /** Warnings produced while fitting the model. */
  warnings: string[];
  /** @internal Scaled residual SSP retained for numerically stable summary calculations. */
  _residualSSPScaled: number[][];
  /** @internal Scaled term SSP matrices retained for numerically stable summary calculations. */
  _termSSPScaled: Record<string, number[][]>;
}
/** Four multivariate test tables and associated matrices.
 * @category Multivariate analysis
 */
export interface ManovaSummary {
  /** Pillai's trace test table. */
  Pillai: MatrixTable;
  /** Wilks' lambda test table. */
  Wilks: MatrixTable;
  /** Hotelling-Lawley trace test table. */
  "Hotelling-Lawley": MatrixTable;
  /** Roy's largest-root test table. */
  Roy: MatrixTable;
  /** Sum-of-squares-and-cross-products matrices, keyed by model term and residuals. */
  SS: Record<string, MatrixTable>;
  /** Generalized roots for each displayed model term. */
  Eigenvalues: MatrixTable;
  /** Regression coefficient matrix with labelled rows and response columns. */
  coef: MatrixTable;
  /** Roy largest-root F approximation is an upper bound. */
  royFIsUpperBound: true;
}

function zeros(r: number, c: number): number[][] { return Array.from({ length: r }, () => new Array<number>(c).fill(0)); }
function cross(a: number[][], b: number[][] = a): number[][] {
  const out = zeros(a[0]?.length ?? 0, b[0]?.length ?? 0);
  for (const [i, row] of a.entries()) for (const [j, v] of row.entries()) for (let k = 0; k < out[j]!.length; k++) out[j]![k]! += v * b[i]![k]!;
  return out;
}
function mul(a: number[][], b: number[][]): number[][] {
  const out = zeros(a.length, b[0]?.length ?? 0);
  for (let i = 0; i < a.length; i++) for (let k = 0; k < (a[0]?.length ?? 0); k++) for (let j = 0; j < (b[0]?.length ?? 0); j++) out[i]![j]! += a[i]![k]! * b[k]![j]!;
  return out;
}
function scaleRows(a: number[][], scales: readonly number[]): number[][] {
  return a.map((row) => row.map((v, j) => v * scales[j]!));
}
function table(rows: string[], cols: string[] | null, values: number[][]): MatrixTable { return { rows, cols, values }; }
function responseParts(formula: string): { names: string[]; rhs: string } {
  const m = /^\s*cbind\s*\((.*)\)\s*~\s*(.+)$/s.exec(formula);
  if (!m) throw new TypeError("the response must be cbind(y1, y2, ...) in a MANOVA formula");
  const names = m[1]!.split(",").map((v) => v.trim());
  if (names.length < 2) throw new RangeError("need multiple responses");
  return { names, rhs: m[2]!.trim() };
}
function responseColumns(data: DataFrame, names: readonly string[]): { data: DataFrame; internal: string[] } {
  const out: Record<string, readonly (number | string | boolean | null)[] | Float64Array> = { ...data };
  const internal: string[] = [];
  for (let i = 0; i < names.length; i++) {
    const name = names[i]!;
    const simple = /^[A-Za-z.][A-Za-z0-9._]*$/.test(name);
    if (simple) { internal.push(name); continue; }
    const sum = /^I\(\s*([A-Za-z.][A-Za-z0-9._]*)\s*\+\s*([A-Za-z.][A-Za-z0-9._]*)\s*\)$/.exec(name);
    const numeric = /^as\.numeric\(\s*([A-Za-z.][A-Za-z0-9._]*)\s*\)$/.exec(name);
    const multiply = /^([A-Za-z.][A-Za-z0-9._]*)\s*\*\s*(-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)$/.exec(name);
    const multiplyReverse = /^(-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*\*\s*([A-Za-z.][A-Za-z0-9._]*)$/.exec(name);
    const key = `.__manova_response_${i}`;
    if (sum) {
      const a = dataColumn(data, sum[1]!); const b = dataColumn(data, sum[2]!);
      out[key] = a.map((v, j) => v + b[j]!);
    } else if (multiply || multiplyReverse) {
      const variable = multiply ? multiply[1]! : multiplyReverse![2]!;
      const factor = Number(multiply ? multiply[2]! : multiplyReverse![1]!);
      out[key] = dataColumn(data, variable).map((v) => v * factor);
    } else if (numeric) {
      const v = data[numeric[1]!];
      if (v === undefined) throw new RangeError(`object '${numeric[1]}' not found`);
      const vals = Array.from(v);
      if (vals.every((x) => typeof x === "number")) out[key] = vals as number[];
      else {
        const levels = [...new Set(vals.filter((x) => x !== null).map(String))].sort();
        const codes = new Map(levels.map((x, j) => [x, j + 1]));
        out[key] = vals.map((x) => x === null ? NaN : codes.get(String(x))!);
      }
    } else throw new TypeError(`unsupported MANOVA response expression: ${name}`);
    internal.push(key);
  }
  return { data: out, internal };
}
function dataColumn(data: DataFrame, name: string): number[] {
  const v = data[name];
  if (v === undefined) throw new RangeError(`object '${name}' not found`);
  const a = Array.from(v);
  if (a.some((x) => x !== null && typeof x !== "number")) throw new TypeError(`response '${name}' must be numeric`);
  return a.map((x) => x === null ? NaN : x as number);
}
function correlationSSP(e: number[][]): { matrix: number[][]; scales: number[] } | null {
  const scales = e.map((row, i) => Math.sqrt(Math.max(0, row[i]!)));
  if (scales.some((v) => !(v > 0) || !Number.isFinite(v))) return null;
  return {
    scales,
    matrix: e.map((row, i) => row.map((v, j) => v / (scales[i]! * scales[j]!))),
  };
}
function rootsFor(e: number[][], h: number[][], tol: number): number[] {
  const c = correlationSSP(e);
  if (c === null) throw new RangeError(`residuals have rank 0 < ${e.length}`);
  const ce = eigen(c.matrix, { symmetric: true });
  const keep = ce.values.map((v, i) => v > tol ? i : -1).filter((i) => i >= 0);
  if (keep.length !== e.length) throw new RangeError(`residuals have rank ${keep.length} < ${e.length}`);
  const q = ce.vectors!;
  const inv = zeros(e.length, e.length);
  for (const k of keep) for (let i = 0; i < e.length; i++) for (let j = 0; j < e.length; j++) {
    inv[i]![j]! += q[i]![k]! * q[j]![k]! / Math.sqrt(ce.values[k]!);
  }
  const hs = h.map((row, i) => row.map((v, j) => v / (c.scales[i]! * c.scales[j]!)));
  const a = mul(mul(inv, hs), inv);
  for (let i = 0; i < a.length; i++) for (let j = i + 1; j < a.length; j++) a[i]![j] = a[j]![i] = (a[i]![j]! + a[j]![i]!) / 2;
  return eigen(a, { symmetric: true }).values;
}
function statRow(roots0: readonly number[], p: number, q: number, v: number, name: ManovaTestName): number[] {
  const roots = roots0.slice(0, Math.min(p, q)).map((x) => Math.max(0, x));
  const s = Math.min(p, q), m = (Math.abs(p - q) - 1) / 2, n0 = (v - p - 1) / 2;
  const pillai = roots.reduce((a, x) => a + x / (1 + x), 0);
  const wilks = roots.reduce((a, x) => a / (1 + x), 1);
  const hotelling = roots.reduce((a, x) => a + x, 0);
  const roy = roots[0] ?? 0;
  let value = NaN, df1 = NaN, df2 = NaN, f = NaN;
  switch (name) {
    case "Pillai":
      value = pillai; df1 = s * (2 * m + s + 1); df2 = s * (2 * n0 + s + 1);
      f = ((2 * n0 + s + 1) / (2 * m + s + 1)) * value / (s - value); break;
    case "Wilks": {
      value = wilks; const t = p * q > 2 ? Math.sqrt((p * p * q * q - 4) / (p * p + q * q - 5)) : 1;
      const u = (p * q - 2) / 4; df1 = p * q; df2 = (v - (p - q + 1) / 2) * t - 2 * u;
      const wt = value ** (1 / t); f = ((1 - wt) / wt) * (df2 / df1); break;
    }
    case "Hotelling-Lawley":
      value = hotelling; df1 = s * (2 * m + s + 1); df2 = 2 * (s * n0 + 1);
      f = (df2 / (df1 * s)) * value; break;
    case "Roy":
      value = roy; df1 = Math.max(p, q); df2 = v - Math.max(p, q) + q;
      f = (df2 / df1) * value; break;
  }
  return [q, value, f, df1, df2, pf1(f, df1, df2, false, false)];
}
/**
 * Fit a multivariate analysis of variance model with sequential (Type I) terms. Equivalent to R's `stats::manova()`.
 * The response is `cbind(y1, y2, ...)`; all four classical MANOVA statistics are available in {@link manovaSummary}.
 *
 * @param formula Multivariate formula, e.g. `"cbind(y1, y2, y3) ~ group + covariate"`.
 * @param data Data frame.
 * @param options Numerical rank tolerance.
 *
 * @category Multivariate analysis
 */
export function manova(formula: string, data: DataFrame, options: ManovaOptions = {}): ManovaFit {
  checkOptions(options, MANOVA_KEYS, "manova"); // generated: option-keys.mjs
  const { names, rhs } = responseParts(formula);
  const tol = options.tol ?? 1e-7;
  if (!(Number.isFinite(tol) && tol >= 0)) throw new RangeError("'tol' must be a non-negative finite number");
  const parsed = parseFormula(`~ ${rhs}`);
  const prepared = responseColumns(data, names);
  const d = design(parsed, prepared.data, { extraVariables: prepared.internal, dropUnusedLevels: true });
  const raw = prepared.internal.map((name) => dataColumn(prepared.data, name));
  const y = d.frame.rows.map((row) => raw.map((col) => col[row]!));
  if (y.some((r) => r.some((v) => !Number.isFinite(v)))) throw new RangeError("NA/NaN/Inf in foreign function call (arg 1)");
  const p = names.length, n = y.length;
  if (p < 2) throw new RangeError("need multiple responses");
  const scales = names.map((_, j) => { let m = 0; for (const row of y) m = Math.max(m, Math.abs(row[j]!)); return m === 0 ? 1 : m; });
  const ys = scaleRows(y, scales.map((s) => 1 / s));
  const full = qr(d.x, { tol });
  const residual = qrResid(full, ys) as number[][];
  const e = cross(residual);
  const cor = correlationSSP(e);
  const rank = cor === null ? 0 : eigen(cor.matrix, { symmetric: true }).values.filter((v) => v > tol).length;
  if (rank < p) throw new RangeError(`residuals have rank ${rank} < ${p}`);
  const coef = qrCoef(full, ys) as number[][];
  const termSSP: Record<string, number[][]> = {};
  const termRoots: Record<string, number[]> = {};
  const termDf: number[] = [];
  const termNames = d.terms.termLabels;
  const assignments = d.assign;
  let prevFit = zeros(n, p);
  let prevRank = 0;
  const interceptCols = assignments.map((a, i) => a === 0 ? i : -1).filter((i) => i >= 0);
  if (interceptCols.length) {
    const q0 = qr(d.x.map((r) => interceptCols.map((j) => r[j]!)), { tol });
    const fit0 = qrFitted(q0, ys) as number[][];
    const h0 = cross(fit0);
    termSSP["(Intercept)"] = h0;
    termRoots["(Intercept)"] = rootsFor(e, h0, tol);
    prevFit = fit0;
    prevRank = q0.rank;
  }
  for (let term = 1; term <= termNames.length; term++) {
    const cols = assignments.map((a, i) => a <= term ? i : -1).filter((i) => i >= 0);
    const xx = d.x.map((r) => cols.map((j) => r[j]!));
    const q = qr(xx, { tol });
    const fit = qrFitted(q, ys) as number[][];
    const diff = fit.map((r, i) => r.map((v, j) => v - prevFit[i]![j]!));
    const h = cross(diff);
    const df = q.rank - prevRank;
    if (df > 0) {
      termSSP[termNames[term - 1]!] = h;
      termRoots[termNames[term - 1]!] = rootsFor(e, h, tol);
      termDf.push(df);
    } else termDf.push(0);
    prevFit = fit; prevRank = q.rank;
  }
  const unscale = (m: number[][]) => m.map((r, i) => r.map((v, j) => v * scales[i]! * scales[j]!));
  return {
    formula, responseNames: names, termNames, termDf, residualDf: n - full.rank,
    residualSSP: unscale(e),
    termSSP: Object.fromEntries(Object.entries(termSSP).map(([k, v]) => [k, unscale(v)])),
    termRoots, coefficients: coef.map((r) => r.map((v, j) => v * scales[j]!)),
    coefficientNames: d.colNames, responseScales: scales, warnings: d.warnings,
    _residualSSPScaled: e, _termSSPScaled: termSSP,
  };
}

/**
 * Summary tables for all four MANOVA statistics, with optional sequential intercept row. Equivalent to R's `summary.manova()`.
 *
 * @param fit A result of {@link manova}.
 * @param options Select a statistic or request the intercept row.
 *
 * @category Multivariate analysis
 */
export function manovaSummary(fit: ManovaFit, options: ManovaSummaryOptions = {}): ManovaSummary {
  checkOptions(options, MANOVA_SUMMARY_KEYS, "manovaSummary"); // generated: option-keys.mjs
  const tol = options.tol ?? 1e-7;
  if (!(Number.isFinite(tol) && tol >= 0)) throw new RangeError("'tol' must be a non-negative finite number");
  const p = fit.responseNames.length;
  const v = fit.residualDf;
  const terms = Object.keys(fit.termSSP).filter((x) => x !== "(Intercept)");
  const names = options.intercept && fit.termSSP["(Intercept)"] ? ["(Intercept)", ...terms] : terms;
  const rootsByTerm: Record<string, number[]> = {};
  for (const name of Object.keys(fit.termSSP)) {
    rootsByTerm[name] = rootsFor(fit._residualSSPScaled, fit._termSSPScaled[name]!, tol);
  }
  const make = (test: ManovaTestName): MatrixTable => {
    const col = test === "Pillai" ? "Pillai" : test === "Wilks" ? "Wilks" : test;
    const rows = names.map((term) => {
      const roots = rootsByTerm[term] ?? [];
      const q = term === "(Intercept)" ? 1 : fit.termDf[fit.termNames.indexOf(term)]!;
      return statRow(roots, p, q, v, test);
    });
    rows.push([v, NaN, NaN, NaN, NaN, NaN]);
    return table([...names, "Residuals"], ["Df", col, "approx F", "num Df", "den Df", "Pr(>F)"], rows);
  };
  const responseLabels = fit.responseNames.map((name) => /^[A-Za-z.][A-Za-z0-9._]*$/.test(name) ? name : "");
  const SS: Record<string, MatrixTable> = {};
  for (const name of [...names, "Residuals"]) {
    const raw = name === "Residuals" ? fit.residualSSP : fit.termSSP[name]!;
    SS[name] = table(responseLabels, responseLabels, raw);
  }
  const Eigenvalues = table(names, null, names.map((name) => rootsByTerm[name] ?? []));
  const coef = table(fit.coefficientNames, responseLabels, fit.coefficients);
  return {
    Pillai: make("Pillai"), Wilks: make("Wilks"), "Hotelling-Lawley": make("Hotelling-Lawley"), Roy: make("Roy"),
    SS, Eigenvalues, coef, royFIsUpperBound: true,
  };
}
